while not self.is_finished(): # scheduler.waiting 和 scheduler.running 都为空 t = perf_counter() output, num_tokens = self.step() # output = [(seq_id_0, [token1,...,token5]), ...] # num_tokens: prefill 时 = 14 (positive), decode 时 = -2 (negative → 取绝对值)
# 吞吐量计算: if num_tokens > 0: prefill_throughput = num_tokens / (perf_counter()-t) # 14 / 0.1s = 140 tok/s else: decode_throughput = -num_tokens / (perf_counter()-t) # 2 / 0.005s = 400 tok/s
for seq_id, token_ids in output: outputs[seq_id] = token_ids pbar.update(1)
# 所有请求完成后, outputs = { # seq_id_0: [token_A1, token_A2, ..., token_A5], # seq_id_1: [token_B1, token_B2, ..., token_B5], # } # 按 seq_id 排序输出, tokenizer.decode → 最终文本
